    "id": "l-b2-3",
    "mode": "listen",
    "level": "B2",
    "theme": "Travail & Entreprise",
    "en": "Had we anticipated the surge in demand, we would have hired extra staff before summer. As it stands, everyone is working overtime to keep up.",
    "fr": "Si nous avions anticipé la hausse de la demande, nous aurions embauché du personnel supplémentaire avant l'été. En l'état actuel, tout le monde fait des heures supplémentaires pour suivre le rythme.",
    "grammarTitle": "Inversion conditionnelle (Had we...)",
